// === Tab: mySketch ===
let lapse = 0;    // timer
let num = 1000;
let pos = [];
let vel = [];

function setup() {
	createCanvas(1112, 834);
	background(0);
  colorMode(HSB, 255);
	for (let i = 0; i < num; i++) {
		pos[i] = createVector(width / 2, height / 2);
		vel[i] = createVector(0, 0);
	}
}

function draw() {
	for (let i = 0; i < pos.length; i++) {
		pos[i].add(vel[i]);

		let rotation = random(TWO_PI);
		vel[i].x += cos(rotation) * 0.1;
		vel[i].y += sin(rotation) * 0.1;

		if (pos[i].x < 0 || pos[i].x > width || pos[i].y < 0 || pos[i].y > height) {
			vel[i].mult(0);
			// removeFromArray(i);
		}

		stroke((frameCount * 2%255), 255, 255);
		line(pos[i].x, pos[i].y, pos[i].x + vel[i].x * 10, pos[i].y + vel[i].y * 10);
	}
}


function mousePressed(){
	// prevents mouse press from registering twice
  if (frameCount - lapse > 15){
    save('pix.jpg');
    lapse = frameCount;
  }
}

